public static int calculateTimeNeeded(int N) {
    if (N <= 1) return 0;
    if ((N & 1) == 1) {             // odd
        return N - 1;
    }
    if ((N & 3) == 0) {              // N is multiple of 4
        return N / 2;
    }
    return N;                        // even but not multiple of 4
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, new ArrayList<>(), new boolean[nums.length], res);
    return res;
}

private void backtrack(int[] nums, List<Integer> temp, boolean[] visited, List<List<Integer>> res) {
    if (temp.size() == nums.length) {
        res.add(new ArrayList<>(temp));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!visited[i]) {
            visited[i] = true;
            temp.add(nums[i]);
            backtrack(nums, temp, visited, res);
            temp.remove(temp.size() - 1);
            visited[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    for (int len = first.length(); len >= 1; len--) {
        for (int start = 0; start <= first.length() - len; start++) {
            String cand = first.substring(start, start + len);
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!s.contains(cand) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    if (cols == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int r = cell[0];
                    int c = cell[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dx[k];
                        int nc = c + dy[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return count;
}

