public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k == 0) {
        return false;
    }
    int[] remCount = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        remCount[r]++;
    }
    if (remCount[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        int opposite = k - r;
        if (r == opposite) { // k is even and r == k/2
            if (remCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remCount[r] != remCount[opposite]) {
                return false;
            }
        }
    }
    return true;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Step 1-3: smallest to largest
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        // Step 4-6: largest to smallest
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int s = totalSum; s >= num; s--) {
                if (dp[k - 1][s - num]) dp[k][s] = true;
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int prev2 = cost[0]; // min cost to reach step 0
    int prev1 = cost[1]; // min cost to reach step 1

    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }

    return Math.min(prev1, prev2);
}

