public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int cur = 0;

    // Build the first window
    for (int i = 0; i < k; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    if (!seen[cur]) {
        seen[cur] = true;
        count++;
    }

    int mask = total - 1;
    for (int i = 1; i <= n - k; i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i + k - 1) - '0');
        if (!seen[cur]) {
            seen[cur] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

