public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // need an opening bracket before this
                balance++;      // pretend we inserted '('
            }
            balance--;          // pair this ')' with a '('
        }
    }
    // Remaining unmatched '(' need closing brackets
    insertions += balance;
    return insertions;
}

