public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    int maxAbs = Math.abs(maxSoFar);
    int minAbs = Math.abs(minSoFar);
    return Math.max(maxAbs, minAbs);
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[50];
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
        if (remaining == 0) {
            break;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();

    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }

    int smallSize = small.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }

    // large currently contains factors in descending order
    Collections.reverse(large);
    int remaining = k - smallSize;
    if (remaining <= large.size()) {
        return large.get(remaining - 1);
    }

    return -1;
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int best = 0;
    java.util.ArrayDeque<Integer> idxStack = new java.util.ArrayDeque<>();
    java.util.ArrayDeque<java.util.Set<String>> setStack = new java.util.ArrayDeque<>();
    idxStack.push(0);
    setStack.push(new java.util.HashSet<String>());
    while (!idxStack.isEmpty()) {
        int idx = idxStack.pop();
        java.util.Set<String> used = setStack.pop();
        if (idx == n) {
            if (used.size() > best) best = used.size();
            continue;
        }
        for (int end = idx + 1; end <= n; end++) {
            String sub = s.substring(idx, end);
            if (!used.contains(sub)) {
                java.util.Set<String> newUsed = new java.util.HashSet<String>(used);
                newUsed.add(sub);
                idxStack.push(end);
                setStack.push(newUsed);
            }
        }
    }
    return best;
}

