public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low == 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        generateStepping(i, low, high, result);
    }
    java.util.Collections.sort(result);
    return result;
}

private static void generateStepping(long current, int low, int high, java.util.List<Integer> result) {
    if (current > high) {
        return;
    }
    if (current >= low) {
        result.add((int) current);
    }
    long lastDigit = current % 10;
    if (lastDigit > 0) {
        generateStepping(current * 10 + (lastDigit - 1), low, high, result);
    }
    if (lastDigit < 9) {
        generateStepping(current * 10 + (lastDigit + 1), low, high, result);
    }
}

public static int countDigitOne(int n) {
    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long high = n / (i * 10);
        long cur = (n / i) % 10;
        long low = n % i;
        if (cur == 0) {
            count += high * i;
        } else if (cur == 1) {
            count += high * i + low + 1;
        } else {
            count += (high + 1) * i;
        }
    }
    return count;
}

