    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    // Precompute adjacency lists
    java.util.ArrayList<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    java.util.Arrays.sort(A); // Sorting helps with duplicates handling (optional)
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int)Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                adj[i].add(j);
            }
        }
    }
    int fullMask = (1 << n) - 1;
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        @Override
        public Integer apply(Integer lastIdx, Integer mask) {
            if (mask == fullMask) return 1;
            long key = (((long)(lastIdx + 1)) << 32) | (mask & 0xffffffffL);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            int count = 0;
            if (lastIdx == -1) {
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0) {
                        count += apply(i, mask | (1 << i));
                    }
                }
            } else {
                for (int nxt : adj[lastIdx]) {
                    if ((mask & (1 << nxt)) == 0) {
                        count += apply(nxt, mask | (1 << nxt));
                    }
                }
            }
            memo.put(key, count);
            return count;
        }
    };
    return dfs.apply(-1, 0);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int maxArea = 0;
    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) maxArea = area;
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    for (int k = 0; k < m + n - 1; k++) {
        if (k % 2 == 0) {
            // even diagonal: start from the bottom of the diagonal
            int i = Math.min(k, m - 1);
            while (i >= 0 && k - i < n) {
                res[index++] = mat[i][k - i];
                i--;
            }
        } else {
            // odd diagonal: start from the top of the diagonal
            int j = Math.min(k, n - 1);
            while (j >= 0 && k - j < m) {
                res[index++] = mat[k - j][j];
                j--;
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }
    if (pivot == -1) {
        return -1;
    }

    int successor = -1;
    for (int j = len - 1; j > pivot; j--) {
        if (digits[j] > digits[pivot]) {
            successor = j;
            break;
        }
    }

    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static boolean isBoomerang(int[][] points) {
    // Check that all three points are distinct
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) return false;
    if (points[0][0] == points[2][0] && points[0][1] == points[2][1]) return false;
    if (points[1][0] == points[2][0] && points[1][1] == points[2][1]) return false;

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Compute twice the signed area of the triangle; non‑zero means not collinear
    long area = (long) (x2 - x1) * (y3 - y1) - (long) (x3 - x1) * (y2 - y1);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0; // or throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;

        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    return Math.max(max, current);
}

public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>(n);
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if ((long) cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur += 1;
            } else {
                while ((cur / 10) % 10 == 9) {
                    cur /= 10;
                }
                cur = cur / 10 + 1;
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize with a value larger than any possible result
    java.util.Arrays.fill(dp, n + 1);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            if (word.length() > 0) {
                result.append(word.reverse());
                word.setLength(0);
            }
            result.append(c); // preserve the space
        } else {
            word.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
